			public function getPreviousOrderID($order_id) {
	$query = $this->db->query("SELECT max(order_id) as pre_order_id FROM `" . DB_PREFIX . "order` WHERE order_id < $order_id and order_status_id > '0' and order_status_id!=7 and order_status_id!=10 and order_status_id!=11");
	return $query->row['pre_order_id'];
}
public function getNextOrderID($order_id) {
	$query = $this->db->query("SELECT min(order_id) as nxt_order_id FROM `" . DB_PREFIX . "order` WHERE order_id > $order_id and order_status_id > '0' and order_status_id!=7 and order_status_id!=10 and order_status_id!=11");
	return $query->row['nxt_order_id'];
}
